package dev.joaomendonca.agendapro.settings.domain;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="tenant_settings") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class TenantSettings{@Id @Column(name="tenant_id",columnDefinition="BINARY(16)") private UUID tenantId;@Column(name="business_name",nullable=false,length=120) private String businessName;@Column(length=30) private String phone;@Column(nullable=false,length=60) private String timezone;@Column(nullable=false,length=3) private String currency;@Column(name="booking_interval_minutes",nullable=false) private int bookingIntervalMinutes;@Column(name="cancellation_hours",nullable=false) private int cancellationHours;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;public TenantSettings(UUID id){tenantId=id;createdAt=Instant.now();update("Meu estabelecimento",null,"America/Sao_Paulo","BRL",30,24);}public void update(String name,String phone,String timezone,String currency,int interval,int cancellation){businessName=name.trim();this.phone=phone==null||phone.isBlank()?null:phone.trim();this.timezone=timezone;this.currency=currency;bookingIntervalMinutes=interval;cancellationHours=cancellation;updatedAt=Instant.now();}}
